properties.query:
let pth_events = SecurityEvent | where EventID == 4624 and AuthenticationPackageName == "NTLM" and LogonType == 3 | summarize pth_time=min(TimeGenerated) by TargetUserName, Computer;
let smb_events = SecurityEvent | where EventID == 5140 | summarize smb_time=min(TimeGenerated) by TargetUserName, Computer;
let da_events = SecurityEvent | where EventID == 4624 and TargetUserName endswith "-admin" or TargetUserName in ("Domain Admins", "Enterprise Admins") | summarize da_time=min(TimeGenerated) by TargetUserName;
pth_events | join kind=inner smb_events on TargetUserName | where smb_time - pth_time between (0min .. 60min)
